; The old road. In from the village on the west, east through the forest at dusk. A camp off the
; road to the south with its fire still going, a path north to the barrow where the road forks,
; and a tree down across the road further east.

[map]
id = road
name = The Old Road
world = 600 290
tileset = forest
size = 60 34
dark = yes
ambient = 0.55          ; dusk, not night: the dark is only to make the fire count
music = Exploring

[legend]
, = leaves
: = road
T = thicket
m = moss
v = tuft
f = fern
o = rock
s = stump
< = log-left
> = log-right
| = trunk
b = bush
/ = canopy-nw
^ = canopy-n
\ = canopy-ne
( = canopy-w
@ = canopy
) = canopy-e
L = canopy-sw
_ = canopy-s
J = canopy-se

