; kind id x y, in tiles, then any settings. Exits and triggers are rectangles from their top left tile.
[objects]
spawn start 2 16 facing=right
spawn barrow 40.5 2
exit village 0 15 h=3 to=village at=east
exit barrow 40 0 w=2 to=barrow

; The camp.
prop campfire 26 23
prop bedroll 22.5 21.5
prop bedroll 29 25
prop crate 21 26
prop barrel 22 26
chest camp 30 22 gold=14
trigger watched 17 7 h=18 say="Someone has been watching the road." set=road-ambush

; The fork.
sign fork 38 13 text="West, the village. North, the barrow."
waypoint stone 44 11

; The far end.
trigger blocked 53 14 h=5 once=no say="No way through to the east."
